  "age_estimate": "Estimated age or 30s",
  "location": "City, Country or State",
  "occupation": "Job title",
  "company": "Company or Independent",
  "education": "School / Degree",
  "needs": ["4 core relationship needs"],
  "hobbies": ["4 active leisure hobbies"],
  "interests": ["4 passions or intellectual pursuits"],
  "values": ["4 guiding principles"],
  "personality": {
    "openness": 0.9,
    "conscientiousness": 0.85,
    "extraversion": 0.75,
    "agreeableness": 0.88,
    "neuroticism": 0.2
  },
  "communication_style": "Conversational description",
  "energy_level": "high",
  "lifestyle": "Daily rhythm and leisure description",
  "love_language": "Primary love language",
  "summary": "3-4 sentences synthesizing what this person's agent seeks in romantic compatibility"
}`;

const userPrompt = `Person Name: ${personName}\nLinkedIn URL: ${linkedinUrl}\nInstagram URL: ${instagramUrl}\nAdditional Notes: ${JSON.stringify(input.raw_data || {})}`;

let profileResult = null;
let usedProvider = 'none';
let errors = [];

async function postJson(url, headers, payload) {
  if (typeof fetch === 'function') {
    const res = await fetch(url, {
      method: 'POST',
      headers: headers,
      body: JSON.stringify(payload)
    });
    if (!res.ok) {
      const errText = await res.text().catch(() => '');
      throw new Error(`HTTP ${res.status}: ${errText.slice(0, 100)}`);
    }
    return await res.json();
  }
  if (typeof this?.helpers?.httpRequest === 'function') {
    return await this.helpers.httpRequest({
      method: 'POST',
      url: url,
      headers: headers,
      body: payload,
      json: true
    });
  }
  throw new Error('No HTTP transport available');
}

