for (let i = 0; i < groqKeys.length; i++) {
  const key = groqKeys[i];
  for (const model of groqModels) {
    try {
      const data = await postJson(
        'https://api.groq.com/openai/v1/chat/completions',
        {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${key}`,
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AgentMatch/1.0'
        },
        {
          model: model,
          messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: userPrompt }
          ],
          temperature: 0.5,
          response_format: { type: 'json_object' }
        }
      );

      if (data && data.choices && data.choices[0] && data.choices[0].message) {
        const content = data.choices[0].message.content;
        profileResult = JSON.parse(content);
        usedProvider = `Groq (Key #${i + 1} - ${model})`;
        break keyLoop;
      }
    } catch (err) {
      errors.push(`Groq Key #${i + 1} (${model}) error: ${err.message}`);
    }
  }
}

if (!profileResult && openAiKey) {
